// Shows an SVG produced by @qr-daddy/qr. The markup is generated by our own renderer
// from the user's text, never taken from user input directly.
export function QrArt({ svg, label, className = "" }: { svg: string; label: string; className?: string }) {
	return <div role="img" aria-label={label} className={`qr-svg ${className}`} dangerouslySetInnerHTML={{ __html: svg }} />;
}
